// ===== FONCTION POUR MÉLANGER LES RÉPONSES ET RECALCULER L'INDEX =====
function shuffleAndUpdateAnswer(options, correctAnswerIndex) {
  const shuffled = [...options];
  const correctAnswer = options[correctAnswerIndex]; // Récupère la bonne réponse
  
  // Mélange le tableau
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  
  // Trouve la nouvelle position de la bonne réponse
  const newIndex = shuffled.indexOf(correctAnswer);
  
  return { options: shuffled, correctIndex: newIndex };
}



